import{_ as t,H as _,f as a,i as r}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"第二季回归丨这次我们一起实战后端存储","description":"","frontmatter":{},"headers":[],"relativePath":"消息队列高手课/第二季回归丨这次我们一起实战后端存储.md","filePath":"消息队列高手课/第二季回归丨这次我们一起实战后端存储.md","lastUpdated":1779821001000}'),p={name:"消息队列高手课/第二季回归丨这次我们一起实战后端存储.md"};function o(n,e,s,i,m,d){return _(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="第二季回归丨这次我们一起实战后端存储" tabindex="-1">第二季回归丨这次我们一起实战后端存储 <a class="header-anchor" href="#第二季回归丨这次我们一起实战后端存储" aria-label="Permalink to &quot;第二季回归丨这次我们一起实战后端存储&quot;">​</a></h1><p>你好，我是李玥，这次我带着一门全新的课程《后端存储实战课》回来了。</p><p>存储这个技术方向，每一个系统都会涉及。我在《消息队列高手课》这个专栏中和你讲过，消息队列的本质也是一个分布式的存储系统。</p><p>不管你的系统业务是什么样的，最终都要落到对数据的管理上。你会发现，凡是那些特别难解决的、让你付出巨大代价的技术问题，几乎都可以归为存储系统的问题。只要最终的“数据”是正确的，剩下的都是小问题。</p><p>因此可以说： <strong>存储是系统中最核心、最重要、最关键的组成部分，没有之一。</strong></p><p>所以，我开设了第二季课程，来专门讲“存储”。</p><p>在更新《消息队列高手课》期间，我发现，相比于“基础篇”和“进阶篇”，课程的最后一部分“案例篇”更受同学们欢迎。不少同学和我反馈，这种结合实战案例来讲解技术知识的方式，既可以快速获得解决实际问题的方法，同时还能学到和实战相关的技术干货，效果不错。</p><p>所以，在第二季，我会全部以实战案例的方式来讲“存储”。以电商不同发展阶段的场景为蓝本，每节课解决一两个大家都会遇到的实际问题，在解题的过程中带你学习相关的存储知识和原理。</p><p>通过学习这门课程，你将收获的不仅是热点存储问题的解决策略，在对电商系统架构、存储系统的认知和设计等方面，都会有所提升。</p><p>好的，我会在《 <a href="https://time.geekbang.org/column/intro/287?utm_term=zeusGVR04&amp;utm_source=geektime&amp;utm_medium=xiaoxiduilie" target="_blank" rel="noreferrer">后端存储实战课</a>》中等你，一起开启一段新的学习旅程。</p>',10)])])}const u=t(p,[["render",o]]);export{c as __pageData,u as default};
